class Solution {
  public int kthSmallestSubarraySum(int[] nums, int k) {
    int lo = Integer.MAX_VALUE, hi = 0;
    for (int x : nums) {
      lo = Math.min(lo, x);
      hi += x;
    }
    // smallest s with at least k subarrays summing to <= s (all values positive: sliding window count)
    while (lo < hi) {
      int mid = lo + (hi - lo) / 2;
      if (countAtMost(nums, mid) >= k) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }

  private long countAtMost(int[] nums, int s) {
    long count = 0;
    int sum = 0;
    for (int l = 0, r = 0; r < nums.length; r++) {
      sum += nums[r];
      while (sum > s) sum -= nums[l++];
      count += r - l + 1;
    }
    return count;
  }
}
